WITH cleaned AS (SELECT *, ROUND(pressure, 0) AS pressure_rounded FROM device_readings WHERE reading_ts > DATE '2025-09-01' AND temp_c BETWEEN 28 AND 29) SELECT *, LEAD(status_bits) OVER w_running AS next_status_bits, LAG(status_bits) OVER w_running AS prev_status_bits, LEAD(pressure_rounded) OVER w_running AS next_pressure_rounded, ROW_NUMBER() OVER w_running AS event_seq FROM cleaned WINDOW w_running AS (PARTITION BY device_code ORDER BY pressure ASC, id ASC)
